export const categories=['食品','医疗','清洁','用品','服务','其他'];
export const todayDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export const withLedger=s=>({...s,ledgerVersion:1,bills:s.bills||[],initialInvestments:s.initialInvestments||{},ledgerScope:s.ledgerScope||s.current||'all'});
export function cents(value,allowZero=false){const t=String(value).trim();if(!/^\d{1,8}(\.\d{1,2})?$/.test(t))throw Error('金额需为有效数字，最多两位小数');const [whole,fraction='']=t.split('.');const n=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(n<(allowZero?0:1)||n>9999999999)throw Error(allowZero?'金额不能小于0':'金额必须大于0');return n;}
export const money=n=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
export function splitCents(total,owners){if(!owners.length)throw Error('请至少选择一只宠物');const base=Math.floor(total/owners.length),rest=total%owners.length;return owners.map((p,i)=>({petId:p.id,petName:p.name,cents:base+(i<rest?1:0)}));}
export const billAmount=(bill,scope='all')=>scope==='all'?bill.cents:bill.allocations.filter(a=>scope==='public'?a.petId===null:a.petId===scope).reduce((s,a)=>s+a.cents,0);
export function summary(state,scope='all',period='',category='全部'){const rows=state.bills.filter(b=>!b.deletedAt&&(!period||b.date.startsWith(period))&&(category==='全部'||b.category===category)&&billAmount(b,scope)>0).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));let expense=0,refund=0,count=0;const byCategory={};for(const b of rows){const n=billAmount(b,scope);if(b.type==='refund')refund+=n;else{expense+=n;count++;byCategory[b.category]=(byCategory[b.category]||0)+n;}}return {rows,expense,refund,net:expense-refund,count,byCategory};}
export function remainingAllocations(state,parentId,excludeId){const p=state.bills.find(b=>b.id===parentId&&!b.deletedAt&&b.type==='expense');if(!p)throw Error('原支出不存在');return p.allocations.map(a=>({...a,cents:a.cents-state.bills.filter(b=>!b.deletedAt&&b.type==='refund'&&b.parentId===parentId&&b.id!==excludeId).reduce((s,b)=>s+b.allocations.filter(x=>x.petId===a.petId).reduce((n,x)=>n+x.cents,0),0)}));}
export function refundAllocations(state,parentId,total,excludeId){const available=remainingAllocations(state,parentId,excludeId),sum=available.reduce((s,a)=>s+a.cents,0);if(total>sum)throw Error('退款金额不能超过剩余可退金额');if(total<=0)throw Error('退款金额必须大于0');const out=available.map(a=>({...a,cents:Number(BigInt(total)*BigInt(a.cents)/BigInt(sum)),remainder:Number(BigInt(total)*BigInt(a.cents)%BigInt(sum))}));let rest=total-out.reduce((s,a)=>s+a.cents,0);for(const a of [...out].sort((a,b)=>b.remainder-a.remainder))if(rest-->0)a.cents++;return out.map(({remainder,...a})=>a);}
function validBill(b){if(!b.id||!['expense','refund'].includes(b.type)||!Number.isInteger(b.cents)||b.cents<1||b.cents>9999999999||!categories.includes(b.category))throw Error('账单金额或分类无效');if(typeof b.name!=='string'||!b.name.trim()||b.name.length>60)throw Error('名称必填且最多60字');if(!/^\d{4}-\d{2}-\d{2}$/.test(b.date)||!Number.isFinite(new Date(b.date+'T12:00').getTime())||todayDateFrom(new Date(b.date+'T12:00'))!==b.date||b.date>todayDate())throw Error('请选择有效日期，不能在未来');if(!Array.isArray(b.allocations)||!b.allocations.length||new Set(b.allocations.map(a=>a.petId)).size!==b.allocations.length||b.allocations.some(a=>!(a.petId===null||typeof a.petId==='string')||typeof a.petName!=='string'||!Number.isInteger(a.cents)||a.cents<0)||b.allocations.reduce((s,a)=>s+a.cents,0)!==b.cents)throw Error('分摊金额合计必须等于账单总额');if((b.note||'').length>500)throw Error('备注最多500字');if(!Array.isArray(b.photos)||b.photos.length>9||b.photos.some(p=>typeof p!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(p)))throw Error('账单照片无效');if(!Number.isFinite(new Date(b.created).getTime()))throw Error('账单创建时间无效');}
const todayDateFrom=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
export function saveBill(state,bill){validBill(bill);const old=state.bills.find(b=>b.id===bill.id);if(old?.deletedAt)throw Error('该账单已删除');if(old&&old.type!==bill.type)throw Error('不能修改账单类型');if(bill.type==='refund'){const available=remainingAllocations(state,bill.parentId,bill.id);const parent=state.bills.find(b=>b.id===bill.parentId);if(bill.category!==parent.category||bill.allocations.some(a=>{const prior=available.find(x=>x.petId===a.petId);return !prior||a.cents>prior.cents;}))throw Error('退款超过原支出对应宠物的可退金额');}else{const refunds=state.bills.filter(b=>!b.deletedAt&&b.parentId===bill.id);if(refunds.length&&old&&(old.cents!==bill.cents||old.category!==bill.category||JSON.stringify(old.allocations)!==JSON.stringify(bill.allocations)))throw Error('已有退款，请先处理退款后修改金额、分类或分摊');const oldOwners=new Set(old?.allocations.map(a=>a.petId)||[]);if(bill.allocations.some(a=>a.petId!==null&&!state.pets.some(p=>p.id===a.petId)&&!oldOwners.has(a.petId)))throw Error('请选择存在的宠物');}return {...state,bills:old?state.bills.map(b=>b.id===bill.id?bill:b):[...state.bills,bill]};}
export function removeBill(state,id){if(state.bills.some(b=>!b.deletedAt&&b.parentId===id))throw Error('请先删除关联退款，再删除原支出');return {...state,bills:state.bills.map(b=>b.id===id?{...b,deletedAt:new Date().toISOString()}:b)};}
export function undoBill(state,id){const b=state.bills.find(b=>b.id===id);if(!b?.deletedAt)return state;const next={...state,bills:state.bills.map(x=>x.id===id?{...x,deletedAt:null}:x)};if(b.type==='refund'){const available=remainingAllocations(state,b.parentId,b.id);if(b.allocations.some(a=>a.cents>(available.find(x=>x.petId===a.petId)?.cents??-1)))throw Error('当前退款余额不足，无法恢复');}return next;}
export function investment(state,scope){const initial=scope==='all'?Object.values(state.initialInvestments).reduce((s,n)=>s+n,0):(state.initialInvestments[scope]||0);const totals=summary(state,scope);return {initial,...totals,total:initial+totals.net};}
export function validateLedger(state){if(state.bills===undefined&&state.initialInvestments===undefined)return;const s=withLedger(state);if(state.ledgerVersion!==1||!Array.isArray(state.bills)||!state.initialInvestments||typeof state.initialInvestments!=='object'||Array.isArray(state.initialInvestments))throw Error('账单备份格式无效');if(new Set(s.bills.map(b=>b.id)).size!==s.bills.length)throw Error('重复账单标识');for(const b of s.bills)validBill(b);for(const n of Object.values(s.initialInvestments))if(!Number.isInteger(n)||n<0||n>9999999999)throw Error('初始投入数据无效');for(const b of s.bills.filter(b=>!b.deletedAt&&b.type==='refund')){const available=remainingAllocations(s,b.parentId,b.id),parent=s.bills.find(x=>x.id===b.parentId);if(b.category!==parent.category||b.allocations.some(a=>a.cents>(available.find(x=>x.petId===a.petId)?.cents??-1)))throw Error('退款引用或金额无效');}}
